ee:variables.ee:set-variable:
%dw 2.0
output application/java
var q = attributes.queryParams default {}
---
{
	invalid: (not isEmpty(q.ids default "")) and ((q.email != null) or (q.phone != null)),
	params: { (ids: q.ids) if (q.ids != null), (email: q.email) if (q.email != null), (phone: q.phone) if (q.phone != null),
		(page: q.page) if (q.page != null), (size: q.size) if (q.size != null) }
}
